import {initializeApp} from 'firebase/app';
import {getAuth,onAuthStateChanged,signInWithPopup,GoogleAuthProvider,signInWithEmailAndPassword,createUserWithEmailAndPassword,sendPasswordResetEmail,sendEmailVerification,signOut,signInWithCustomToken} from 'firebase/auth';
import {esc,money,date,pct,cents,decimal,icon,badge,empty,button,field,area,select,check,title} from './ui.js';

const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const state={configured:false,cfg:{},user:null,auth:null,mode:sessionStorage.getItem('sam.mode')||'user',data:{},notifications:[],epoch:0,sellerConnected:false,bootError:''};
const isNative=()=>!!window.SamNative;
const adminApp=()=>isNative()&&window.SamNative.isAdminApp();
const checked=(f,n)=>f.elements[n]?.checked===true;
const val=(f,n)=>f.elements[n]?.value||'';
const admin=()=>state.user?.isAdmin&&state.mode==='admin';
const owner=()=>state.user?.isOwner;
const productBadge=s=>s==='pending'?'<span class="status warn">Aguardando aprovação</span>':badge(s);
const link=(label,route)=>`<a class="button secondary" href="#${route}">${label}</a>`;
const toast=(message,error=false)=>{const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),8500);};
const busy=(form,on)=>form.querySelectorAll('button[type=submit]').forEach(x=>x.disabled=on);
async function api(path,{method='GET',body,headers={},anonymous=false}={}){
  const token=!anonymous?await state.auth?.currentUser?.getIdToken():'';
  let r;try{r=await fetch(`/api${path}`,{method,headers:{...(token?{Authorization:`Bearer ${token}`} :{}),...(body!==undefined?{'Content-Type':'application/json'}:{}),...headers},...(body!==undefined?{body:JSON.stringify(body)}:{}),cache:'no-store'});}catch{throw new Error('Sem conexão com a central. Confira sua internet.');}
  const data=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(data.error?.message||'Não foi possível concluir.');e.code=data.error?.code;throw e;}return data;
}
async function collection(path){let items=[],cursor='',pages=0;do{const r=await api(path+(path.includes('?')?'&':'?')+(cursor?'cursor='+encodeURIComponent(cursor):''));items.push(...r.items);cursor=r.nextCursor;pages++;}while(cursor&&pages<10);if(cursor)toast('Exibindo os primeiros 1.000 registros. Refine a consulta antes de usar totais.');return items;}
function dialog(name,html){modal.innerHTML=`<div class="dialog-head"><h2>${esc(name)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fechar">${icon('close')}</button></div><div id="dialog-error"></div>${html}`;if(!modal.open)modal.showModal();}
function dialogError(e){const node=modal.querySelector('#dialog-error');if(node){node.innerHTML=`<div class="error-text" role="alert">${esc(e.message)}</div>`;node.scrollIntoView({block:'nearest'});}else toast(e.message,true);}
function hero(){return `<section class="hero"><div><div class="eyebrow">UMA PLATAFORMA. TODA A SUA REDE.</div><h2>Conecte produtos.<br>Multiplique oportunidades.</h2><p>Venda, indique e acompanhe seus negócios em um só lugar. No celular e no computador, com a mesma central.</p><div class="row">${state.user?link('Explorar produtos','explorar'):button('Fazer parte da rede','login')}${link('Como funciona','implantacao')}</div></div><div class="hero-visual"><div class="hub"><img src="/logo.svg" alt=""><div><strong>Central da plataforma</strong><small>Configurações e operações compartilhadas</small></div></div><div class="connected-apps"><div>${icon('monitor')}<br>Painel web<small>Controle principal</small></div><div>${icon('phone')}<br>Aplicativos<small>ADM e usuário</small></div></div></div></section>`;}
function chrome(){
  const menu=admin()?[['central','Visão geral','home'],['catalogo','Catálogo','grid'],['pedidos-adm','Pedidos','bag'],...(owner()?[['pessoas','Pessoas','users'],['repasses','Comissões','wallet']]:[]),['novidades-adm','Novidades','news'],...(owner()?[['projetos-adm','Projetos','building'],['integracoes','Integrações','plug'],['configuracoes','Configurações','settings'],['historico','Histórico','history']]:[])]:[['explorar','Explorar','grid'],['pedidos','Meus pedidos','bag'],['vendas','Quero vender','package'],['afiliados','Quero indicar','users'],...(state.cfg.projectsEnabled?[['projetos','Projetos','building']]:[]),['novidades','Novidades','news'],['perfil','Meu perfil','person']];
  const route=location.hash.slice(1)||'explorar',u=state.user,initials=(u?.fullName||u?.email||'SC').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
  app.innerHTML=`<aside class="sidebar"><a class="brand" href="#${admin()?'central':'explorar'}"><img src="/logo.svg" alt=""><div><strong>${esc(state.cfg.brand||'SAM CONECTA')}</strong><small>${admin()?'Central de administração':'Produtos, pessoas e oportunidades'}</small></div></a><div class="nav-label">${admin()?'ADMINISTRAÇÃO':'MINHA PLATAFORMA'}</div><nav class="nav">${menu.map(([r,label,i])=>`<a href="#${r}" class="${route===r?'active':''}">${icon(i)}${label}</a>`).join('')}</nav><div class="sidebar-footer"><div class="server-badge"><span class="dot ${state.configured?'ok':''}"></span>${state.configured?'Central configurada':'Aguardando configuração'}</div><small>Versão 0.1.0 · revisão ${Number(state.cfg.revision||0)}</small><div class="gap-top"><a href="#implantacao">Ajuda e implantação</a></div></div></aside><div class="nav-backdrop" data-action="menu"></div><div class="shell"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><div class="breadcrumb">${admin()?'Administração':'Marketplace'}<strong>${esc(menu.find(x=>x[0]===route)?.[1]||'Sua central')}</strong></div><div class="top-actions"><span class="central-chip">${admin()?'Controle compartilhado':'Sua rede de negócios'}</span>${u?.isAdmin?button(admin()?'Área do usuário':'Abrir ADM','switch-mode','secondary small'):''}${u?`<button class="icon-btn" data-action="notifications" aria-label="Notificações">${icon('bell')}<span id="unread" class="counter hidden">0</span></button><div class="avatar">${esc(initials)}</div><div class="account">${esc((u.fullName||'Minha conta').split(' ').slice(0,2).join(' '))}<small>${u.isOwner?'Proprietário':u.isAdmin?'Administrador':'Minha conta'}</small></div><button class="icon-btn" data-action="logout" aria-label="Sair da conta">${icon('logout')}</button>`:button(state.configured?'Entrar':'Ativar plataforma',state.configured?'login':'setup','dark')}</div></header><main class="content" id="content"></main></div>`;
  updateUnread();
}
function setupNotice(){return `<div class="strip info">A plataforma aguarda a conexão com seu Firebase. Cadastre as configurações na hospedagem para liberar contas, produtos e operações reais.</div>`;}
const noLogin=()=>empty('Entre para continuar','Use sua conta para acompanhar pedidos, vender produtos e indicar para sua rede.',button('Entrar ou cadastrar','login'),'person');
async function route(){
  const epoch=++state.epoch,r=location.hash.slice(1)||'explorar';chrome();const root=document.querySelector('#content');root.innerHTML='<div class="loading"><span class="spinner"></span>Carregando a central…</div>';
  if(adminApp()&&state.user&&!state.user.isAdmin){root.innerHTML=empty('Conta sem acesso administrativo','Entre com a conta proprietária ou uma conta autorizada.',button('Trocar conta','logout'),'shield');return;}
  if(!state.configured){root.innerHTML=title('Sua plataforma começa aqui','Web, ADM e usuários conectados à mesma operação.')+hero()+setupNotice()+setupPage();return;}
  if(state.cfg.maintenance&&!state.user?.isAdmin&&r!=='perfil'&&r!=='implantacao'){root.innerHTML=empty('Plataforma em manutenção','A administração está atualizando a central. Volte em breve.','','settings');return;}
  try{
    let html='';
    if(['explorar','catalogo'].includes(r))html=await catalogPage(r==='catalogo');
    else if(r==='central'&&admin())html=await dashboard();
    else if(r==='implantacao')html=title('Como colocar sua central no ar','A configuração inicial conecta os aplicativos à sua plataforma.')+setupPage();
    else if(!state.user)html=noLogin();
    else if(r==='perfil')html=profilePage();
    else if(r==='vendas')html=await salesPage();
    else if(r==='afiliados')html=await affiliatePage();
    else if(r==='pedidos'||r==='pedidos-adm'&&admin())html=await ordersPage(r==='pedidos-adm');
    else if(r==='integracoes'&&owner()&&admin())html=await integrationsPage();
    else if(r==='configuracoes'&&owner()&&admin())html=settingsPage();
    else if(r==='pessoas'&&owner()&&admin())html=await usersPage();
    else if(r==='repasses'&&owner()&&admin())html=await payoutsPage();
    else if(['novidades','novidades-adm'].includes(r))html=await newsPage(r==='novidades-adm'&&admin());
    else if(['projetos','projetos-adm'].includes(r))html=await projectsPage(r==='projetos-adm'&&owner()&&admin());
    else if(r==='historico'&&owner()&&admin())html=await auditPage();
    else html=empty('Página indisponível','Escolha uma opção no menu para continuar.',link('Explorar produtos','explorar'),'info');
    if(epoch!==state.epoch)return;root.innerHTML=html;
    const productId=new URLSearchParams(location.search).get('product');if(productId&&r==='explorar'&&!state.openedProduct){state.openedProduct=true;const p=state.data.catalog?.find(p=>p.id===productId);if(p)productDetail(p);}
  }catch(e){if(epoch===state.epoch)root.innerHTML=title('Não foi possível carregar','Confira a conexão com a sua central.')+empty('Operação indisponível',e.message,button('Tentar novamente','refresh'),'info');}
}
function setupPage(){return `<div class="grid two"><section class="panel"><div class="panel-head"><h2>Configuração inicial</h2>${badge('draft')}</div><ol class="checklist"><li>Envie a pasta do projeto ao GitHub e importe o repositório na Netlify.</li><li>Crie um projeto Firebase exclusivo e ative Authentication, Google, e-mail/senha e Firestore.</li><li>Preencha as variáveis de <code>.env.example</code> na Netlify e publique novamente.</li><li>Entre com o e-mail proprietário verificado para abrir o ADM.</li><li>Publique seus termos e sua privacidade em Configurações.</li><li>Cadastre o Mercado Pago em Integrações, teste e homologue uma compra.</li><li>Nos APKs, informe a mesma URL HTTPS publicada.</li></ol><p class="setup-footer">O ZIP inclui o guia completo para Firebase, GitHub, Netlify, Mercado Pago e Android.</p></section><section class="panel"><h2>Uma regra para todos os canais</h2><p>O servidor valida cada operação. O painel web e o ADM do celular consultam essa mesma regra, e o usuário recebe o resultado autorizado.</p><div class="callout"><h3>Conexão verificada por capacidade</h3><p>O teste informa se a API respondeu, autenticou e quais operações foram verificadas. Uma resposta positiva de login não comprova um pagamento completo.</p></div><div class="callout"><h3>Novos serviços por conectores</h3><p>Firebase e Mercado Pago estão implementados nesta versão. Outros bancos e pagamentos precisam de adaptadores. Uma troca de banco também precisa levar os dados existentes.</p></div><div class="callout"><h3>Aplicativos ligados à central</h3><p>As configurações são atualizadas a cada 20 segundos com a tela aberta. Cada comando também é conferido pelo servidor, mesmo se a tela ainda estiver desatualizada.</p></div></section></div>`;}
async function catalogPage(moderation=false){
  if(moderation&&!admin())throw new Error('Entre como administrador.');
  const products=await collection(moderation?'/admin/products':'/catalog');state.data.catalog=products;
  return title(moderation?'Seu catálogo':'Encontre sua próxima oportunidade',moderation?'Revise produtos e controle a publicação na rede.':'Produtos da comunidade, organizados para você comprar e indicar.',state.user?button('Adicionar produto','new-product'):button('Começar a vender','login'))+(moderation?'':hero())+`<div class="catalog-tools"><div class="search">${icon('search')}<input class="input" id="product-search" placeholder="Buscar por produto ou descrição" aria-label="Buscar produtos"></div><select class="filter" id="category-filter" aria-label="Categoria"><option value="">Todas as categorias</option>${state.cfg.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><span class="tag">${products.length} produtos carregados</span></div><div id="product-results">${productCards(products,moderation)}</div>`;
}
function productCards(products,moderation=false){return products.length?`<div class="product-grid">${products.map(p=>`<article class="product-card">${p.image?`<img class="product-image" src="${esc(p.image)}" alt="${esc(p.title)}" loading="lazy">`:`<div class="product-image placeholder">${icon(p.category==='Imóveis'?'building':'package')}</div>`}<div class="product-body"><div class="row"><span class="product-category">${esc(p.category)}</span>${moderation?productBadge(p.status):''}</div><h3>${esc(p.title)}</h3><div class="product-price">${money(p.priceCents)}</div><div class="affiliate-tag">${p.affiliateBp&&state.cfg.affiliatesEnabled?`${icon('users')} Comissão de ${pct(p.affiliateBp)} por venda confirmada`:p.saleMode==='manual'?'Negociação acompanhada pela equipe':'Compra com checkout Mercado Pago'}</div><div class="row"><button class="button secondary small" data-action="product" data-id="${esc(p.id)}">Ver detalhes</button>${moderation?`<button class="button small" data-action="moderate" data-id="${esc(p.id)}">Gerenciar</button>`:`<button class="button small" data-action="buy" data-id="${esc(p.id)}" ${!p.stock?'disabled':''}>${p.stock?p.saleMode==='manual'?'Tenho interesse':'Comprar':'Indisponível'}</button>`}</div></div></article>`).join('')}</div>`:empty('Seu catálogo está começando','Os produtos publicados aparecerão aqui, com categoria, preço e comissão.',state.user?button('Cadastrar meu primeiro produto','new-product'):button('Quero participar','login'));}
function productDetail(p){dialog(p.title,`${p.image?`<img class="detail-image" src="${esc(p.image)}" alt="${esc(p.title)}">`:''}<p class="gap-top">${esc(p.category)} · ${p.saleMode==='manual'?'Negociação assistida':'Pagamento online'}</p><div class="product-price">${money(p.priceCents)}</div><div class="description">${esc(p.description)}</div><p class="gap-top">Comissão de indicação: ${pct(p.affiliateBp)}. Disponibilidade: ${Number(p.stock)} unidade(s).</p><div class="dialog-actions">${state.cfg.affiliatesEnabled?`<button class="button secondary" data-action="affiliate-link" data-id="${esc(p.id)}">Obter link de indicação</button>`:''}<button class="button" data-action="buy" data-id="${esc(p.id)}" ${!p.stock?'disabled':''}>${p.saleMode==='manual'?'Solicitar atendimento':'Comprar com Mercado Pago'}</button></div>`);}
async function dashboard(){
  const [orders,products,users]=await Promise.all([collection('/admin/orders'),collection('/admin/products'),owner()?collection('/admin/users'):Promise.resolve([])]);state.data.orders=orders;
  const paid=orders.filter(o=>['paid','partially_refunded'].includes(o.paymentStatus));const fee=paid.reduce((s,o)=>s+(o.recognizedFeeCents||0),0);
  return title('Tudo conectado. Você no controle.','Acompanhe a operação compartilhada pelo painel web e pelo ADM do celular.',owner()?link('Gerenciar integrações','integracoes'):link('Ver pedidos','pedidos-adm'))+`<div class="grid four"><div class="panel metric"><div class="label">Vendas confirmadas ${icon('bag')}</div><div class="value">${paid.length}</div><div class="note">Entre os pedidos carregados</div></div><div class="panel metric"><div class="label">Receita bruta da taxa ${icon('wallet')}</div><div class="value">${money(fee)}</div><div class="note">Antes das tarifas do provedor</div></div><div class="panel metric"><div class="label">Atendimentos pendentes ${icon('bell')}</div><div class="value">${orders.filter(o=>o.paymentStatus==='manual_review'||o.checkoutError||o.needsAttention).length}</div><div class="note">Negociações e revisões</div></div><div class="panel metric"><div class="label">Produtos na rede ${icon('package')}</div><div class="value">${products.length}</div><div class="note">${products.filter(p=>p.status==='pending').length} aguardando aprovação</div></div></div><div class="grid two gap-top"><section class="panel"><div class="panel-head"><h2>Operação da central</h2><span class="status good">Revisão ${state.cfg.revision}</span></div><div class="activity-item"><div class="activity-icon">${icon('monitor')}</div><div><strong>Painel web principal</strong><p>Configurações, integrações, taxas e histórico.</p></div></div><div class="activity-item"><div class="activity-icon">${icon('phone')}</div><div><strong>ADM no celular</strong><p>As operações passam pelo mesmo servidor e usam as regras atuais.</p></div></div><div class="activity-item"><div class="activity-icon">${icon('users')}</div><div><strong>Área do usuário</strong><p>${users.length} contas carregadas · ${state.cfg.marketplaceEnabled?'Catálogo habilitado':'Catálogo pausado'}.</p></div></div></section><section class="panel"><h2>Próximos atendimentos</h2>${orders.filter(o=>o.paymentStatus==='manual_review').slice(0,4).map(o=>`<div class="activity-item"><div class="activity-icon">${icon('bag')}</div><div><strong>${esc(o.productTitle)}</strong><p>${money(o.totalCents)} · Atendimento humano</p><button class="button secondary small" data-action="order" data-id="${esc(o.id)}">Abrir pedido</button></div></div>`).join('')||'<p>Nenhuma negociação assistida pendente nos registros carregados.</p>'}</section></div><section class="panel gap-top"><div class="panel-head"><h2>Pedidos recentes</h2>${link('Ver todos','pedidos-adm')}</div>${ordersTable([...orders].sort((a,b)=>String(b.createdAt).localeCompare(a.createdAt)).slice(0,5))}</section><p class="footer-note">Totais calculados sobre até 1.000 registros carregados. Comissões de afiliados são separadas da receita da plataforma.</p>`;
}
function profilePage(){const u=state.user,c=state.cfg;return title('Seu perfil','Complete os dados para vender, comprar e indicar com sua conta.')+(!u.emailVerified?`<div class="strip">Confirme seu e-mail para comprar. ${button('Enviar confirmação','verify-email','secondary small')}</div>`:'')+`<section class="panel"><form data-form="profile" data-terms-version="${esc(c.termsVersion)}"><div class="form-grid">${field('Nome completo / razão social','fullName',u.fullName,'text','required maxlength="120" autocomplete="name"')}${field('CPF ou CNPJ','documentNumber',u.documentNumber,'text','required maxlength="22" autocomplete="off"')}${field('Telefone com DDD','phone',u.phone,'tel','required autocomplete="tel"')}${field('E-mail da conta','email',u.email,'email','disabled')}<div class="wide">${area('Endereço completo','address',u.address,'required maxlength="500" autocomplete="street-address"')}</div></div>${check('Quero vender meus produtos','seller',u.seller)}${check('Quero indicar produtos e receber comissões','affiliate',u.affiliate)}<hr><h3>Termos de uso · ${esc(c.termsVersion)}</h3><div class="terms">${esc(c.termsText||'A administração ainda precisa publicar os termos.')}</div><h3>Privacidade</h3><div class="terms">${esc(c.privacyText||'A administração ainda precisa publicar a política de privacidade.')}</div>${check('Li e aceito os termos de uso e a política de privacidade desta versão.','acceptTerms',false)}<p class="footer-note">O cadastro registra os dados informados. O preenchimento do CPF/CNPJ não comprova a identidade.</p><div class="dialog-actions"><button class="button" type="submit" ${!c.termsText||!c.privacyText?'disabled':''}>Salvar meu perfil</button></div></form></section>`;}
async function salesPage(){const products=await collection('/products/mine');state.data.mine=products;return title('Venda para a sua rede','Cadastre seus produtos. A administração aprova a publicação.',button('Novo produto','new-product'))+(!state.user.completed?`<div class="strip">Complete o cadastro antes de cadastrar um produto. ${link('Completar perfil','perfil')}</div>`:'')+`<section class="panel"><div class="panel-head"><div><h2>Recebimentos com Mercado Pago</h2><p>Conecte sua conta para receber suas vendas online.</p></div>${state.sellerConnected?'<span class="status good">Conta vinculada</span>':'<span class="status warn">Vinculação pendente</span>'}</div><div class="row">${button(state.sellerConnected?'Reconectar conta':'Conectar Mercado Pago','seller-connect','secondary')}<small>Taxa da plataforma: ${pct(state.cfg.platformFeeBp)}. A comissão do afiliado é definida por produto.</small></div></section><section class="panel gap-top"><div class="panel-head"><h2>Meus produtos</h2><span class="tag">${products.length} carregados</span></div>${products.length?`<div class="table-wrap"><table><thead><tr><th>Produto</th><th>Valor</th><th>Comissão</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${products.map(p=>`<tr><td><strong>${esc(p.title)}</strong><small>${esc(p.category)}</small></td><td>${money(p.priceCents)}</td><td>${pct(p.affiliateBp)}</td><td>${productBadge(p.status)}</td><td><button class="button secondary small" data-action="edit-product" data-id="${esc(p.id)}">Editar</button></td></tr>`).join('')}</tbody></table></div>`:empty('Seu primeiro produto começa aqui','Adicione imagem, descrição, preço e a comissão para quem indicar.',button('Cadastrar produto','new-product'))}</section>`;}
function productForm(p={}){dialog(p.id?'Editar produto':'Cadastrar produto',`<form data-form="product" data-id="${esc(p.id||'')}"><div class="form-grid">${field('Nome do produto','title',p.title,'text','required maxlength="120"')}${select('Categoria','category',state.cfg.categories,p.category||state.cfg.categories[0])}${field('Preço em R$','price',decimal(p.priceCents),'text','required inputmode="decimal"')}${field('Comissão do afiliado (%)','affiliate',decimal(p.affiliateBp),'text','required inputmode="decimal"')}${select('Como acontece a venda','saleMode',[['online','Pagamento online'],['manual','Negociação assistida']],p.saleMode||'online')}${field('Unidades disponíveis','stock',p.stock??1,'number','required min="0" max="1000000"')}<div class="wide">${area('Descrição do produto','description',p.description,'required minlength="10" maxlength="6000"')}</div><div class="wide">${field('URL HTTPS da imagem (opcional)','image',p.image?.startsWith('https:')?p.image:'','url')}<label class="field"><span>Ou escolha uma foto</span><input class="input" name="photo" type="file" accept="image/jpeg,image/png,image/webp"><small>A foto será reduzida para até 250 KB. Produtos de vendedores passam por aprovação.</small></label><input type="hidden" name="existingImage" value="${esc(p.image||'')}"></div></div><p>Taxa da plataforma: ${pct(state.cfg.platformFeeBp)}. A comissão é calculada sobre o valor da venda confirmada.</p><div class="dialog-actions"><button class="button" type="submit">Salvar produto</button></div></form>`);}
async function affiliatePage(){const rows=await collection('/commissions');state.data.commissions=rows;const earned=rows.reduce((s,c)=>s+c.earnedCents,0),paid=rows.reduce((s,c)=>s+c.paidCents,0);return title('Sua indicação tem valor','Compartilhe produtos com seu link. A comissão acompanha o pagamento confirmado.',link('Escolher produtos','explorar'))+(!state.cfg.affiliatesEnabled?'<div class="strip">O programa de afiliados está pausado.</div>':'')+`<div class="grid three"><div class="panel metric"><div class="label">Comissões apuradas</div><div class="value">${money(earned)}</div></div><div class="panel metric"><div class="label">Repasses registrados</div><div class="value">${money(paid)}</div></div><div class="panel metric"><div class="label">Pendente de repasse</div><div class="value">${money(earned-paid)}</div></div></div><section class="panel gap-top"><h2>Como funciona</h2><p>No produto, toque em “Obter link de indicação”. A compra realizada por esse link fica vinculada à sua conta. Cancelamentos, estornos e contestações ajustam a comissão.</p><p>O repasse ao afiliado é realizado pela administração e registrado com a referência da transferência. Esta versão não executa transferências automáticas.</p></section><section class="panel gap-top"><h2>Minhas comissões</h2>${commissionsTable(rows,false)}</section>`;}
function ordersTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Pedido / produto</th><th>Valor</th><th>Pagamento</th><th>Data</th><th>Ação</th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.productTitle)}</strong><small>${esc(o.id.slice(-10))}${o.checkoutError?' · Checkout em revisão':''}${o.needsAttention?' · Atenção ao estoque':''}</small></td><td>${money(o.totalCents)}</td><td>${badge(o.paymentStatus)}</td><td class="nowrap">${date(o.createdAt)}</td><td><button class="button secondary small" data-action="order" data-id="${esc(o.id)}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum pedido por aqui','As compras e solicitações de negociação aparecerão nesta lista.');}
async function ordersPage(all){const rows=await collection(all?'/admin/orders':'/orders');state.data.orders=rows;return title(all?'Pedidos da plataforma':'Meus pedidos',all?'Pagamentos online e negociações que precisam da sua equipe.':'Acompanhe suas compras e vendas na mesma conta.')+`<section class="panel">${ordersTable([...rows].sort((a,b)=>String(b.createdAt).localeCompare(a.createdAt)))}</section>`;}
async function orderDialog(oid){const o=await api('/orders/'+oid);state.data.selectedOrder=o;dialog('Detalhes do pedido',`<h3>${esc(o.productTitle)}</h3><div class="row">${badge(o.paymentStatus)}${badge(o.fulfillment)}</div><div class="product-price">${money(o.totalCents)}</div><p>Código: <code>${esc(o.id)}</code><br>Criado em ${date(o.createdAt)}</p><p>Taxa da plataforma: ${money(o.platformCents)}<br>Comissão da indicação: ${money(o.affiliateCents)}</p>${o.manualReference?`<p>Referência: ${esc(o.manualReference)}</p>`:''}${o.saleMode==='manual'?'<div class="strip info">A equipe foi avisada. A conclusão desta negociação depende de atendimento humano.</div>':'<p>O pagamento é confirmado no servidor pela API do Mercado Pago e pelo webhook assinado.</p>'}${o.checkoutError?'<div class="strip">A criação do checkout precisa ser revisada no Mercado Pago. Evite repetir o pedido antes da conferência.</div>':''}<div class="dialog-actions">${o.checkoutUrl&&o.buyerId===state.user.uid&&['pending','awaiting_checkout'].includes(o.paymentStatus)?`<button class="button" data-action="open-checkout" data-id="${esc(o.id)}">Abrir pagamento</button>`:''}${o.saleMode==='online'?`<button class="button secondary" data-action="sync-order" data-id="${esc(o.id)}">Consultar pagamento</button>`:''}${state.user.isAdmin&&o.paymentStatus==='manual_review'?`<button class="button" data-action="manual-confirm" data-id="${esc(o.id)}">Registrar venda confirmada</button><button class="button secondary" data-action="manual-cancel" data-id="${esc(o.id)}">Cancelar negociação</button>`:''}${state.user.isAdmin&&['paid','partially_refunded'].includes(o.paymentStatus)?`<button class="button secondary" data-action="fulfill" data-id="${esc(o.id)}">Atualizar entrega</button>`:''}</div>`);}
async function integrationsPage(){const data=await api('/admin/integrations');state.data.integrations=data;return title('Todas as conexões, em uma central','Configure os serviços usados pela plataforma e confira o resultado de cada teste.')+`<div class="strip info">Os testes verificam capacidades específicas. “Autenticado” não significa que pagamentos, estornos e notificações já foram homologados.</div><div class="grid two">${data.providers.map(p=>{const d=p.id==='mercadopago'?data.mercadopago:p.id==='firebase'?data.firebase:null,h=d?.health;return `<section class="panel"><div class="connection"><div class="provider-icon ${p.id==='firebase'?'firebase':''}">${icon(p.kind==='database'?'database':'wallet')}</div><div><h3>${esc(p.name)}</h3><p>${p.kind==='database'?'Banco de dados':'Pagamentos'}</p></div><div class="connection-status"><span class="status ${h?.authenticated?'good':p.implemented?'warn':''}">${h?.authenticated?'Autenticação verificada':p.implemented?d?.configured?'Aguardando teste':p.id==='firebase'?'Base configurada':'Aguardando configuração':'Conector necessário'}</span></div></div><div class="capabilities">${p.capabilities.map(x=>`<small>${esc(x)}</small>`).join('')}</div><p>${esc(p.description)}</p><div class="connection-bottom gap-top"><small>${h?`Último teste: ${date(h.checkedAt)}`:p.id==='firebase'?esc(d.projectId):'Ainda sem teste concluído'}</small>${p.id==='mercadopago'?button('Configurar','configure-mp','secondary small'):''}${p.implemented?`<button class="button small" data-action="test-integration" data-id="${p.id}">Testar conexão</button>`:button('Ver requisitos','adapter-help','secondary small')}</div></section>`;}).join('')}</div><section class="panel gap-top"><h2>Troca de banco com seus dados preservados</h2><p>O Firebase guarda autenticação, configurações e operações desta versão. Uma troca exige um adaptador para o destino, migração dos registros e teste antes da ativação.</p>${button('Como adicionar outra integração','adapter-help','secondary')}</section>`;}
function mpForm(){const c=state.data.integrations.mercadopago;dialog('Conectar Mercado Pago',`<form data-form="mercadopago" data-revision="${c.revision}"><p>As credenciais são criptografadas no servidor. Campos vazios preservam os valores salvos.</p>${select('Ambiente','environment',[['test','Testes'],['production','Produção']],c.environment)}${field(`Access Token${c.fields.accessToken?' · salvo':''}`,'accessToken','','password','autocomplete="new-password"')}${field(`Segredo da assinatura Webhook${c.fields.webhookSecret?' · salvo':''}`,'webhookSecret','','password','autocomplete="new-password"')}${field(`Client ID para OAuth de vendedores${c.fields.clientId?' · salvo':''}`,'clientId','','text','autocomplete="off"')}${field(`Client Secret para OAuth${c.fields.clientSecret?' · salvo':''}`,'clientSecret','','password','autocomplete="new-password"')}<p class="footer-note">Ao salvar credenciais, os pagamentos são pausados até um novo teste e a reativação em Configurações. Nenhuma chave é devolvida ao aplicativo.</p><div class="dialog-actions"><button class="button" type="submit">Salvar conexão</button></div></form>`);}
function settingsPage(){const c=state.cfg;return title('Configurações da central','As regras salvas aqui valem para os aplicativos e para o navegador.')+`<section class="panel"><form data-form="settings" data-revision="${c.revision}"><div class="settings-section"><h2>Identidade e acesso</h2><div class="form-grid">${field('Nome da plataforma','brand',c.brand,'text','required maxlength="70"')}${field('Taxa da plataforma (%)','fee',decimal(c.platformFeeBp),'text','required inputmode="decimal"')}</div>${check('Modo de manutenção','maintenance',c.maintenance,'Pausa operações dos usuários. A administração mantém acesso.')}${check('Habilitar catálogo e vendas','marketplaceEnabled',c.marketplaceEnabled)}${check('Habilitar indicações de afiliados','affiliatesEnabled',c.affiliatesEnabled)}${check('Habilitar pagamentos Mercado Pago','paymentsEnabled',c.paymentsEnabled,'Exige credenciais testadas e PAYMENTS_ENABLED=true na Netlify.')}${check('Exibir projetos de aportes','projectsEnabled',c.projectsEnabled,'Exibe projetos publicados e permite registrar interesse. Sem cobrança nem rendimento automático nesta versão.')}</div><div class="settings-section"><h2>Categorias do catálogo</h2>${area('Uma categoria por linha','categories',c.categories.join('\n'),'required maxlength="2500"')}</div><div class="settings-section"><h2>Termos e privacidade</h2><p>Publique os textos específicos da sua operação. Ao alterar os textos, altere também a versão para solicitar um novo aceite.</p>${field('Versão dos termos','termsVersion',c.termsVersion,'text','required maxlength="80"')}${area('Termos de uso publicados','termsText',c.termsText,'maxlength="30000"')}${area('Política de privacidade publicada','privacyText',c.privacyText,'maxlength="30000"')}</div><div class="row"><span class="tag">Revisão carregada: ${c.revision}</span><button class="button right" type="submit">Salvar configurações</button></div></form></section>`;}
async function usersPage(){const rows=await collection('/admin/users');state.data.users=rows;return title('Pessoas da sua rede','Gerencie acesso de usuários e administradores.')+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${rows.map(u=>`<tr><td><strong>${esc(u.fullName||'Cadastro incompleto')}</strong><small>${esc(u.email)}</small></td><td>${u.role==='admin'?'Administrador':u.seller&&u.affiliate?'Vendedor e afiliado':u.seller?'Vendedor':u.affiliate?'Afiliado':'Usuário'}</td><td>${badge(u.status)}</td><td>${u.uid===state.user.uid?'<small>Sua conta</small>':`<button class="button secondary small" data-action="manage-user" data-id="${esc(u.uid)}">Gerenciar</button>`}</td></tr>`).join('')}</tbody></table></div></section>`;}
function commissionsTable(rows,payout){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Venda</th><th>Apurado</th><th>Repassado</th><th>Diferença</th>${payout?'<th>Ação</th>':''}</tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.productTitle)}</strong><small>${esc(c.orderId.slice(-10))}</small></td><td>${money(c.earnedCents)}</td><td>${money(c.paidCents)}</td><td>${money(c.earnedCents-c.paidCents)}</td>${payout?`<td><button class="button secondary small" data-action="payout" data-id="${esc(c.id)}" ${c.earnedCents<=c.paidCents?'disabled':''}>Registrar repasse</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Nenhuma comissão apurada','As comissões entram aqui após a confirmação de uma venda indicada.','','wallet');}
async function payoutsPage(){const rows=await collection('/admin/commissions');state.data.commissions=rows;return title('Comissões e repasses','Confira as comissões e registre as transferências realizadas aos afiliados.')+`<div class="strip info">Registrar um repasse documenta uma transferência externa já realizada. Este botão não movimenta dinheiro.</div><section class="panel">${commissionsTable(rows,true)}</section>`;}
async function newsPage(edit){const rows=await collection(edit?'/admin/news':'/news');state.data.news=rows;return title('Novidades da plataforma','Comunicados e oportunidades para a sua rede.',edit?button('Publicar novidade','new-news'):'')+`<div class="stack">${rows.length?rows.map(n=>`<article class="panel">${n.image?`<img class="detail-image" src="${esc(n.image)}" alt="" loading="lazy">`:''}<div class="row gap-top"><h2>${esc(n.title)}</h2>${edit?`<span class="status">${n.published?'Publicado':'Oculto'}</span>`:''}</div><div class="description">${esc(n.body)}</div><div class="row gap-top"><small>${date(n.updatedAt)}</small>${edit?`<button class="button secondary small right" data-action="edit-news" data-id="${esc(n.id)}">Editar</button>`:''}</div></article>`).join(''):empty('As novidades vão aparecer aqui','A administração pode publicar comunicados para todos os usuários.','','news')}</div>`;}
function newsForm(n={}){dialog(n.id?'Editar novidade':'Nova publicação',`<form data-form="news" data-id="${esc(n.id||'')}">${field('Título','title',n.title,'text','required maxlength="160"')}${area('Conteúdo','body',n.body,'required minlength="5" maxlength="10000"')}${field('Imagem HTTPS (opcional)','image',n.image,'url')}${check('Publicar para os usuários','published',n.published??true)}<div class="dialog-actions"><button class="button" type="submit">Salvar publicação</button></div></form>`);}
async function projectsPage(edit){const rows=await collection(edit?'/admin/projects':'/projects');state.data.projects=rows;let requests=[];if(edit)requests=await collection('/admin/project-requests');return title('Projetos e aportes',edit?'Prepare os projetos e controle quando aparecem para sua rede.':'Conheça os projetos publicados pela plataforma.',edit?button('Criar projeto','new-project'):'')+`<div class="strip info">Este módulo cadastra projetos, estimativas e manifestações de interesse. Recebimento de aportes, titularidade, distribuição e custódia ainda precisam de implementação específica. Nenhum rendimento é creditado automaticamente.</div><div class="grid two">${rows.length?rows.map(p=>`<section class="panel">${p.image?`<img class="detail-image" src="${esc(p.image)}" alt="">`:''}<div class="row gap-top"><h2>${esc(p.title)}</h2>${edit?badge(p.status):''}</div><p class="description">${esc(p.description)}</p><p>Valor mínimo: <strong>${money(p.minimumCents)}</strong><br>Meta do projeto: <strong>${money(p.targetCents)}</strong><br>Estimativa mensal cadastrada: <strong>${pct(p.estimatedMonthlyBp)}</strong></p><p class="footer-note">Estimativa informada pela administração; não é rendimento realizado.</p><div class="gap-top"><button class="button secondary" data-action="${edit?'edit-project':'project-interest'}" data-id="${esc(p.id)}">${edit?'Editar projeto':'Registrar interesse'}</button></div></section>`).join(''):empty('Projetos ainda não publicados','A administração controla a criação e a publicação deste módulo.','','building')}</div>${edit?`<section class="panel gap-top"><h2>Manifestações de interesse</h2>${requests.length?`<div class="table-wrap"><table><thead><tr><th>Projeto</th><th>Conta</th><th>Valor de interesse</th><th>Data</th></tr></thead><tbody>${requests.map(r=>`<tr><td>${esc(r.projectTitle)}</td><td><code>${esc(r.uid)}</code></td><td>${money(r.amountCents)}</td><td>${date(r.createdAt)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Nenhuma manifestação registrada.</p>'}</section>`:''}`;}
function projectForm(p={}){dialog(p.id?'Editar projeto':'Novo projeto',`<form data-form="project" data-id="${esc(p.id||'')}">${field('Nome do projeto / pacote','title',p.title,'text','required maxlength="120"')}${area('Descrição','description',p.description,'required minlength="10" maxlength="10000"')}<div class="form-grid">${field('Valor mínimo (R$)','minimum',decimal(p.minimumCents||10000),'text','required inputmode="decimal"')}${field('Meta do projeto (R$)','target',decimal(p.targetCents||10000000),'text','required inputmode="decimal"')}${field('Estimativa mensal (%)','estimate',decimal(p.estimatedMonthlyBp),'text','required inputmode="decimal"')}${select('Situação','status',[['draft','Rascunho'],['published','Publicado'],['paused','Pausado']],p.status||'draft')}</div>${field('Imagem HTTPS','image',p.image,'url')}<p>A publicação também depende da opção “Exibir projetos de aportes”, nas configurações da central.</p><div class="dialog-actions"><button class="button" type="submit">Salvar projeto</button></div></form>`);}
async function auditPage(){const rows=await collection('/admin/audit');return title('Histórico de operações','Ações administrativas registradas pelo servidor.')+`<section class="panel">${rows.map(a=>`<div class="activity-item"><div class="activity-icon">${icon('shield')}</div><div><strong>${esc(a.action)}</strong><p>Alvo: <code>${esc(a.target)}</code> · Autor: <code>${esc(a.actor)}</code></p><small>${date(a.createdAt)}</small></div></div>`).join('')||'<p>Nenhuma ação registrada.</p>'}</section>`;}
function loginForm(signup=false){dialog(signup?'Crie sua conta':'Bem-vindo à sua rede',`<p>${signup?'Use seu e-mail ou sua conta Google para começar.':'Entre para continuar de onde parou.'}</p>${button('Continuar com Google','google','secondary full')}<div class="divider">ou entre com e-mail</div><form data-form="${signup?'signup':'login'}">${field('E-mail','email','','email','required autocomplete="email"')}${field('Senha','password','','password',`required minlength="8" autocomplete="${signup?'new-password':'current-password'}"`)}<button type="submit" class="button full">${signup?'Criar minha conta':'Entrar'}</button></form><div class="row gap-top">${button(signup?'Já tenho conta':'Criar uma conta',signup?'login':'signup','ghost small')}${signup?'':button('Esqueci minha senha','forgot','ghost small')}</div>`);}
async function loadMe(){const data=await api('/me');state.user=data.user;state.cfg=data.settings;state.sellerConnected=data.sellerConnected;if(adminApp()&&state.user.isAdmin)state.mode='admin';}
function updateUnread(){const last=Number(localStorage.getItem('sam.read.'+(state.user?.uid||''))||0),count=state.notifications.filter(n=>Date.parse(n.createdAt)>last).length,node=document.querySelector('#unread');if(node){node.textContent=count>99?'99+':count;node.classList.toggle('hidden',!count);}}
async function poll(){if(!state.user||document.hidden)return;try{const before=state.cfg.revision;await loadMe();if(state.cfg.revision!==before){toast('As configurações da central foram atualizadas.');const revisionNode=document.querySelector('.sidebar-footer small');if(revisionNode)revisionNode.textContent=`Versão 0.1.0 · revisão ${state.cfg.revision}`;if(!['configuracoes','perfil'].includes(location.hash.slice(1)))await route();}const r=await api('/notifications');const old=new Set(state.notifications.map(n=>n.id));if(state.notificationInitialized&&isNative())for(const n of r.items.filter(n=>!old.has(n.id)).slice(0,3))window.SamNative.notify(n.title,n.message,n.id);state.notifications=r.items;state.notificationInitialized=true;updateUnread();}catch(e){if(['SUSPENDED','INVALID_SESSION'].includes(e.code)){toast(e.message,true);await signOut(state.auth);}}}
function nativeExternal(url){if(isNative())window.SamNative.openExternal(url);else location.assign(url);}
async function buy(pid){if(!state.user){loginForm();return;}const p=[...(state.data.catalog||[]),...(state.data.mine||[])].find(p=>p.id===pid);if(!p)throw new Error('Atualize o catálogo e tente novamente.');state.data.buyProduct=p;dialog(p.saleMode==='manual'?'Solicitar atendimento':'Confirmar pedido',`<h3>${esc(p.title)}</h3><div class="product-price">${money(p.priceCents)}</div><p>${p.saleMode==='manual'?'Ao confirmar, a administração e o vendedor serão avisados para acompanhar a negociação.':'Você será enviado ao checkout do Mercado Pago. A confirmação do pagamento volta para a central e para o aplicativo.'}</p><form data-form="buy" data-id="${esc(pid)}" data-key="${crypto.randomUUID().replace(/-/g,'')}"><div class="dialog-actions"><button class="button" type="submit">${p.saleMode==='manual'?'Solicitar atendimento':'Continuar para o pagamento'}</button></div></form>`);}
function findProduct(pid){return [...(state.data.catalog||[]),...(state.data.mine||[])].find(p=>p.id===pid);}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;event.preventDefault();
  try{
    if(a==='close-modal')modal.close();
    else if(a==='menu'){document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.nav-backdrop').classList.toggle('open');}
    else if(a==='setup'){location.hash='implantacao';if(!state.configured)document.querySelector('.checklist')?.scrollIntoView({behavior:'smooth'});}
    else if(a==='refresh')await route();
    else if(a==='login'||a==='signup'){if(!state.configured){toast('Configure o Firebase antes de abrir contas.');return;}loginForm(a==='signup');}
    else if(a==='forgot'){dialog('Recuperar acesso',`<form data-form="forgot">${field('Seu e-mail','email','','email','required autocomplete="email"')}<button type="submit" class="button full">Enviar instruções</button></form>`);}
    else if(a==='google'){if(isNative())window.SamNative.openAuthentication();else await signInWithPopup(state.auth,new GoogleAuthProvider());}
    else if(a==='logout'){modal.close();await signOut(state.auth);}
    else if(a==='verify-email'){await sendEmailVerification(state.auth.currentUser);toast('Confira sua caixa de entrada. Depois de confirmar, saia e entre novamente.');}
    else if(a==='switch-mode'){state.mode=admin()?'user':'admin';sessionStorage.setItem('sam.mode',state.mode);location.hash=admin()?'central':'explorar';await route();}
    else if(a==='product')productDetail(findProduct(id));
    else if(a==='new-product'){if(!state.user){loginForm();return;}if(!state.user.completed){location.hash='perfil';toast('Complete seu cadastro para publicar.');return;}productForm();}
    else if(a==='edit-product')productForm(findProduct(id));
    else if(a==='buy')await buy(id);
    else if(a==='affiliate-link'){
      if(!state.user){loginForm();return;}if(!state.user.affiliate||!state.user.completed){toast('Ative seu perfil de afiliado para indicar.');location.hash='perfil';modal.close();return;}
      const url=new URL('/',location.origin);url.searchParams.set('product',id);url.searchParams.set('ref',state.user.uid);url.hash='explorar';
      dialog('Seu link de indicação',`<p>Compartilhe este link com quem se interessar pelo produto.</p>${field('Link exclusivo','affiliateLink',url.href,'text','readonly')}<div class="dialog-actions">${button('Copiar link','copy-affiliate')}</div>`);
    }
    else if(a==='copy-affiliate'){const input=modal.querySelector('[name=affiliateLink]');input.select();try{await navigator.clipboard.writeText(input.value);toast('Link copiado.');}catch{document.execCommand('copy');toast('Link selecionado para copiar.');}}
    else if(a==='order')await orderDialog(id);
    else if(a==='sync-order'){el.disabled=true;await api('/orders/'+id+'/sync',{method:'POST',body:{}});await orderDialog(id);}
    else if(a==='open-checkout'){const o=state.data.selectedOrder;nativeExternal(o.checkoutUrl);}
    else if(a==='manual-confirm'){const o=state.data.selectedOrder;dialog('Registrar recebimento externo',`<p>Confirme apenas depois da conclusão real da negociação.</p><form data-form="manual-confirm" data-id="${esc(id)}">${field('Valor recebido (R$)','amount',decimal(o.totalCents),'text','required inputmode="decimal"')}${field('Referência do contrato / comprovante','reference','','text','required minlength="5" maxlength="180"')}<button type="submit" class="button full">Registrar venda confirmada</button></form>`);}
    else if(a==='manual-cancel'){dialog('Cancelar negociação',`<p>Esta ação encerra a solicitação e devolve a disponibilidade ao produto.</p><form data-form="manual-cancel" data-id="${esc(id)}"><button type="submit" class="button full">Confirmar cancelamento</button></form>`);}
    else if(a==='fulfill'){dialog('Atualizar entrega',`<form data-form="fulfill" data-id="${esc(id)}">${select('Etapa','fulfillment',[['processing','Em preparação'],['shipped','Enviado'],['completed','Concluído']],state.data.selectedOrder.fulfillment)}<button type="submit" class="button full">Salvar etapa</button></form>`);}
    else if(a==='seller-connect'){const result=await api('/seller/connect',{method:'POST',body:{}});nativeExternal(result.url);}
    else if(a==='configure-mp')mpForm();
    else if(a==='test-integration'){el.disabled=true;const r=await api('/admin/integrations/'+id+'/test',{method:'POST',body:{}});dialog('Resultado da conexão',`<div class="row"><span class="status ${r.authenticated?'good':'bad'}">${r.authenticated?'Autenticação verificada':'Falha na conexão'}</span></div><div class="gap-top">${r.checks.map(c=>`<p>${icon(c.ok?'check':'info')} ${esc(c.name)} · ${c.ok?'verificado':'pendente'}</p>`).join('')}</div><div class="strip info">${esc(r.scope)}</div><p>Conferido em ${date(r.checkedAt)}.</p>`);}
    else if(a==='adapter-help')dialog('Adicionar uma nova integração','<p>Cada serviço possui autenticação, formato de dados, eventos e operações diferentes. É necessário implementar seu conector no servidor e testar cada capacidade.</p><p>Para um novo banco, o processo inclui cópia dos dados, comparação, migração de identidade e plano de retorno. Colar uma chave não transfere os registros.</p><p>O projeto inclui <code>docs/CONECTORES.md</code> com os contratos e os pontos de extensão.</p>');
    else if(a==='manage-user'){const u=state.data.users.find(u=>u.uid===id);dialog('Gerenciar usuário',`<p><strong>${esc(u.fullName)}</strong><br>${esc(u.email)}</p><p>Documento: ${esc(u.documentNumber||'Não informado')}<br>Telefone: ${esc(u.phone||'Não informado')}<br>Endereço: ${esc(u.address||'Não informado')}</p><form data-form="user" data-id="${esc(id)}">${select('Acesso','status',[['active','Ativo'],['suspended','Desativado']],u.status)}${select('Permissão','role',[['user','Usuário'],['admin','Administrador operacional']],u.role)}<button type="submit" class="button full">Salvar acesso</button></form>`);}
    else if(a==='moderate'){const p=findProduct(id);dialog('Publicação do produto',`<h3>${esc(p.title)}</h3><form data-form="moderate" data-id="${esc(id)}">${select('Situação','status',[['published','Publicado'],['paused','Pausado'],['rejected','Recusado']],p.status)}<button type="submit" class="button full">Salvar publicação</button></form>`);}
    else if(a==='payout'){const c=state.data.commissions.find(c=>c.id===id);dialog('Registrar repasse externo',`<p>Pendente de repasse: <strong>${money(c.earnedCents-c.paidCents)}</strong>. Efetue a transferência no seu provedor e registre a referência aqui.</p><form data-form="payout" data-id="${esc(id)}">${field('Valor transferido (R$)','amount',decimal(c.earnedCents-c.paidCents),'text','required inputmode="decimal"')}${field('ID do comprovante / transferência','reference','','text','required minlength="5" maxlength="180"')}<button type="submit" class="button full">Registrar transferência realizada</button></form>`);}
    else if(a==='new-news'||a==='edit-news')newsForm(a==='edit-news'?state.data.news.find(n=>n.id===id):{});
    else if(a==='new-project'||a==='edit-project')projectForm(a==='edit-project'?state.data.projects.find(p=>p.id===id):{});
    else if(a==='project-interest'){const p=state.data.projects.find(p=>p.id===id);dialog('Manifestar interesse',`<h3>${esc(p.title)}</h3><p>Esta solicitação registra interesse para atendimento. Nenhum dinheiro será cobrado ou creditado.</p><form data-form="interest" data-id="${esc(id)}">${field('Valor de interesse (R$)','amount',decimal(p.minimumCents),'text','required inputmode="decimal"')}<button type="submit" class="button full">Enviar interesse à administração</button></form>`);}
    else if(a==='notifications'){localStorage.setItem('sam.read.'+state.user.uid,String(Date.now()));updateUnread();dialog('Notificações da sua central',state.notifications.map(n=>`<div class="activity-item"><div class="activity-icon">${icon('bell')}</div><div><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><small>${date(n.createdAt)}</small>${n.orderId?`<div class="gap-top"><button class="button secondary small" data-action="order" data-id="${esc(n.orderId)}">Abrir pedido</button></div>`:''}</div></div>`).join('')||'<p>Nenhuma notificação disponível.</p>');}
  }catch(e){if(modal.open)dialogError(e);else toast(e.message,true);}finally{if(el.isConnected)el.disabled=false;}
});

async function photo(file){if(!file?.size)return '';if(file.size>15_000_000)throw new Error('Use uma foto de até 15 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Use uma imagem JPG, PNG ou WebP.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let data;for(const q of [.85,.7,.5,.3]){data=canvas.toDataURL('image/jpeg',q);if(data.length<340000)return data;}throw new Error('Use uma foto menor.');}
document.addEventListener('submit',async event=>{
  const f=event.target;if(!f.matches('[data-form]'))return;event.preventDefault();busy(f,true);const type=f.dataset.form,id=f.dataset.id;
  try{
    if(type==='login'){await signInWithEmailAndPassword(state.auth,val(f,'email'),val(f,'password'));return;}
    if(type==='signup'){const user=await createUserWithEmailAndPassword(state.auth,val(f,'email'),val(f,'password'));await sendEmailVerification(user.user);toast('Conta criada. Confira o e-mail para confirmar seu cadastro.');return;}
    if(type==='forgot'){await sendPasswordResetEmail(state.auth,val(f,'email'));toast('Se existir uma conta para esse e-mail, você receberá instruções.');modal.close();return;}
    if(type==='profile'){await api('/profile',{method:'PUT',body:{fullName:val(f,'fullName'),documentNumber:val(f,'documentNumber'),phone:val(f,'phone'),address:val(f,'address'),seller:checked(f,'seller'),affiliate:checked(f,'affiliate'),acceptTerms:checked(f,'acceptTerms'),termsVersion:f.dataset.termsVersion}});await loadMe();}
    else if(type==='settings'){await api('/admin/settings',{method:'PUT',body:{brand:val(f,'brand'),platformFeeBp:cents(val(f,'fee')),categories:val(f,'categories').split('\n').map(x=>x.trim()).filter(Boolean),termsVersion:val(f,'termsVersion'),termsText:val(f,'termsText'),privacyText:val(f,'privacyText'),maintenance:checked(f,'maintenance'),marketplaceEnabled:checked(f,'marketplaceEnabled'),affiliatesEnabled:checked(f,'affiliatesEnabled'),projectsEnabled:checked(f,'projectsEnabled'),paymentsEnabled:checked(f,'paymentsEnabled'),expectedRevision:Number(f.dataset.revision)}});await loadMe();}
    else if(type==='mercadopago'){await api('/admin/integrations/mercadopago',{method:'PUT',body:{accessToken:val(f,'accessToken'),webhookSecret:val(f,'webhookSecret'),clientId:val(f,'clientId'),clientSecret:val(f,'clientSecret'),environment:val(f,'environment'),expectedRevision:Number(f.dataset.revision)}});await loadMe();}
    else if(type==='product'){const pic=await photo(f.elements.photo.files[0]);await api('/products'+(id?'/'+id:''),{method:id?'PUT':'POST',body:{title:val(f,'title'),description:val(f,'description'),category:val(f,'category'),priceCents:cents(val(f,'price')),affiliateBp:cents(val(f,'affiliate')),saleMode:val(f,'saleMode'),stock:Number(val(f,'stock')),image:pic||val(f,'image')||val(f,'existingImage')}});}
    else if(type==='buy'){
      const q=new URLSearchParams(location.search);let ref=q.get('product')===id?q.get('ref')||'':'';
      const result=await api('/orders',{method:'POST',headers:{'Idempotency-Key':f.dataset.key},body:{productId:id,affiliateId:ref,client:isNative()?adminApp()?'android-adm':'android':'web'}});
      modal.close();if(result.checkoutUrl)nativeExternal(result.checkoutUrl);else{toast('Pedido registrado.');location.hash='pedidos';await route();await orderDialog(result.id);}return;
    }
    else if(type==='moderate')await api('/admin/products/'+id+'/status',{method:'PUT',body:{status:val(f,'status')}});
    else if(type==='user')await api('/admin/users/'+id,{method:'PUT',body:{status:val(f,'status'),role:val(f,'role')}});
    else if(type==='payout')await api('/admin/commissions/'+id+'/payout',{method:'POST',body:{amountCents:cents(val(f,'amount')),reference:val(f,'reference')}});
    else if(type==='manual-confirm')await api('/admin/orders/'+id,{method:'PUT',body:{action:'confirm',totalCents:cents(val(f,'amount')),reference:val(f,'reference')}});
    else if(type==='manual-cancel')await api('/admin/orders/'+id,{method:'PUT',body:{action:'cancel'}});
    else if(type==='fulfill')await api('/admin/orders/'+id,{method:'PUT',body:{action:'fulfill',fulfillment:val(f,'fulfillment')}});
    else if(type==='news')await api('/admin/news',{method:'POST',body:{id,title:val(f,'title'),body:val(f,'body'),image:val(f,'image'),published:checked(f,'published')}});
    else if(type==='project')await api('/admin/projects',{method:'POST',body:{id,title:val(f,'title'),description:val(f,'description'),minimumCents:cents(val(f,'minimum')),targetCents:cents(val(f,'target')),estimatedMonthlyBp:cents(val(f,'estimate')),status:val(f,'status'),image:val(f,'image')}});
    else if(type==='interest')await api('/project-requests',{method:'POST',body:{projectId:id,amountCents:cents(val(f,'amount'))}});
    modal.close();toast(type==='interest'?'Interesse enviado. Nenhum valor foi cobrado.':'Alteração registrada na central.');await route();await poll();
  }catch(e){if(modal.open&&modal.contains(f))dialogError(e);else toast(e.message,true);}finally{if(f.isConnected)busy(f,false);}
});
document.addEventListener('input',event=>{if(!['product-search','category-filter'].includes(event.target.id))return;const q=(document.querySelector('#product-search')?.value||'').toLocaleLowerCase('pt-BR'),category=document.querySelector('#category-filter')?.value;const list=state.data.catalog.filter(p=>(!category||p.category===category)&&`${p.title} ${p.description}`.toLocaleLowerCase('pt-BR').includes(q));document.querySelector('#product-results').innerHTML=productCards(list,location.hash==='#catalogo');});
window.addEventListener('hashchange',()=>{modal.close();route();});
window.addEventListener('focus',()=>poll());
window.completeMobileLogin=async(code,verifier)=>{try{const r=await api('/mobile/exchange',{method:'POST',anonymous:true,body:{code,verifier}});await signInWithCustomToken(state.auth,r.customToken);}catch(e){toast(e.message,true);}};
window.onNativeReturn=async(orderId)=>{if(!state.user){state.pendingNativeOrder=orderId;toast('Entre na sua conta para conferir o pedido.');return;}try{location.hash='pedidos';await route();await orderDialog(orderId);}catch(e){toast(e.message,true);}};
async function boot(){
  try{
    const result=await api('/bootstrap',{anonymous:true});state.configured=result.configured;state.cfg=result.settings;
    if(state.configured){state.auth=getAuth(initializeApp(result.firebase));state.auth.languageCode='pt-BR';onAuthStateChanged(state.auth,async user=>{
      try{if(user){await loadMe();if(state.user.isAdmin&&!sessionStorage.getItem('sam.mode'))state.mode='admin';modal.close();if(!state.user.completed&&!state.user.isOwner)location.hash='perfil';else if(state.user.isAdmin&&(adminApp()||(!location.hash||location.hash==='#explorar')))location.hash='central';await route();await poll();const returned=state.pendingNativeOrder||new URLSearchParams(location.search).get('order');if(returned&&!state.openedReturnOrder){state.openedReturnOrder=true;state.pendingNativeOrder='';await orderDialog(returned);}if(isNative())window.SamNative.webReady();}
        else{state.user=null;state.mode='user';state.notifications=[];state.notificationInitialized=false;await route();if(isNative())window.SamNative.webReady();}}
      catch(e){state.user=null;toast(e.message,true);await route();}
    });}else await route();
    setInterval(poll,20000);
  }catch(e){state.bootError=e.message;app.innerHTML=`<main class="startup"><img src="/logo.svg" width="64" height="64" alt=""><h1>A central ainda não respondeu</h1><p>${esc(e.message)}</p>${button('Tentar novamente','reload')}<p class="gap-top">Abra o projeto pelo servidor de desenvolvimento ou pela URL publicada na Netlify.</p></main>`;document.querySelector('[data-action=reload]')?.addEventListener('click',()=>location.reload());}
}
boot();
